-- 0039 postgresql: up. The schema MariaDB has after migration 0038, in PostgreSQL, as one
-- migration (#232): the start of the PostgreSQL track, numbered after the MariaDB migrations it
-- replaces, which stay in git's history. Written from MariaDB's information_schema and read
-- through by hand. What changed on the way, and why:
--
-- - Integers: tinyint and smallint are smallint, int and mediumint integer, an unsigned
--   smallint integer (it held up to 65535); float is real. AUTO_INCREMENT is an identity
--   GENERATED BY DEFAULT, so the copy and an archived row put back keep their ids.
-- - Text: tinytext to longtext are text; char(n) is varchar(n), as PostgreSQL pads char(n)
--   with spaces MariaDB never returned. An enum is a varchar with a CHECK on its values.
-- - Dates: datetime and timestamp are timestamp(0), seconds as MariaDB kept them. The CHECKs
--   that refused zero dates go: PostgreSQL has no zero date to refuse.
-- - JSON columns are json, not jsonb: json keeps the text as written, which the edit journal
--   compares a row's JSON against to undo it.
-- - Collation: the database sorts in Polish (ICU pl, set when it is created). A column MariaDB
--   compared byte by byte (utf8mb4_bin) is COLLATE "C". The unique keys MariaDB enforced
--   without case on names, an artist's name with its disambiguation, a label's name, a feat
--   type, an alternative name, are unique on lower(): case does not count, Polish letters do,
--   as with utf8mb4_polish_ci. The two prefix keys (feattype(64), altname(190)) are whole.
-- - Names: the columns MariaDB called ID are id, as PostgreSQL folds unquoted names anyway.
--   Index names are unique in a schema here, so labels' "name" and artists_everyweek's "id"
--   are u_labels_name and u_artists_everyweek_id; an index that repeated the primary key goes.
-- - unaccent, from the image's contrib, lets the search match without accents (Jkl_Db).

CREATE EXTENSION IF NOT EXISTS unaccent;

CREATE TABLE albums (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    legal varchar(1) NOT NULL DEFAULT 'y' CHECK (legal IN ('y', 'n')),
    title text,
    release_type varchar(11) NOT NULL DEFAULT 'album' CHECK (release_type IN ('album', 'ep', 'mixtape', 'compilation', 'beat_tape', 'single', 'other')),
    urlname text NOT NULL,
    labelid integer,
    self_released smallint NOT NULL DEFAULT 0,
    year date,
    release_date_precision varchar(5) NOT NULL DEFAULT 'day' CHECK (release_date_precision IN ('day', 'month', 'year')),
    announced smallint NOT NULL DEFAULT 0,
    premier text NOT NULL,
    media_mc smallint,
    catalog_mc text,
    media_cd smallint,
    catalog_cd text,
    media_lp smallint,
    catalog_lp text,
    media_digital smallint NOT NULL DEFAULT 0,
    catalog_digital text,
    epfor integer,
    singiel smallint,
    addedby integer,
    added timestamp(0) DEFAULT CURRENT_TIMESTAMP,
    updatedby integer,
    updated timestamp(0),
    viewed integer NOT NULL DEFAULT 0,
    cover text,
    description text,
    artistabout text NOT NULL,
    notes text,
    status integer NOT NULL DEFAULT 999,
    PRIMARY KEY (id)
);
CREATE INDEX i_albums_labelid ON albums (labelid);
CREATE INDEX i_albums_viewed ON albums (viewed);

CREATE TABLE album_artist_lookup (
    albumid integer NOT NULL DEFAULT 0,
    artistid integer NOT NULL DEFAULT 0,
    role varchar(8) NOT NULL DEFAULT 'main' CHECK (role IN ('main', 'featured')),
    position smallint NOT NULL DEFAULT 1,
    credited_as text,
    status integer NOT NULL DEFAULT 999
);
CREATE INDEX i_album_artist_lookup_artistid ON album_artist_lookup (artistid);
CREATE UNIQUE INDEX u_album_artist_lookup ON album_artist_lookup (albumid, artistid);

CREATE TABLE album_covers (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    albumid integer NOT NULL,
    variant varchar(4) COLLATE "C" NOT NULL CHECK (variant IN ('orig', '600', '300', '75')),
    path varchar(190) COLLATE "C" NOT NULL,
    width integer NOT NULL,
    height integer NOT NULL,
    sha256 varchar(64) COLLATE "C" NOT NULL,
    mime varchar(32) COLLATE "C" NOT NULL,
    source varchar(32) COLLATE "C" NOT NULL,
    sourceurl varchar(500) COLLATE "C",
    licence varchar(64) COLLATE "C",
    main varchar(1) COLLATE "C" NOT NULL DEFAULT 'y' CHECK (main IN ('y', 'n')),
    needs_upgrade smallint NOT NULL DEFAULT 0,
    added timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id)
);
CREATE INDEX i_album_covers_album ON album_covers (albumid);
CREATE UNIQUE INDEX u_album_covers ON album_covers (albumid, variant, sha256);

CREATE TABLE album_lookup (
    songid integer NOT NULL DEFAULT 0,
    albumid integer NOT NULL DEFAULT 0,
    disc smallint NOT NULL DEFAULT 1,
    track integer NOT NULL DEFAULT 0,
    status integer NOT NULL DEFAULT 999
);
CREATE INDEX i_album_lookup_albumid ON album_lookup (albumid, disc, track);
CREATE INDEX i_album_lookup_songid ON album_lookup (songid);

CREATE TABLE album_merges (
    id integer NOT NULL,
    into_id integer NOT NULL,
    operation_id integer,
    merged timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id)
);
CREATE INDEX i_album_merges_into ON album_merges (into_id);

CREATE TABLE album_prices (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    link text NOT NULL,
    albumid integer NOT NULL DEFAULT 0,
    shopid integer NOT NULL DEFAULT 0,
    hits integer NOT NULL DEFAULT 0,
    added timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    addedby integer NOT NULL DEFAULT 0,
    PRIMARY KEY (id)
);

CREATE TABLE album_promomixes (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    urlname varchar(40) NOT NULL DEFAULT '0',
    promomix text NOT NULL,
    size text NOT NULL,
    hits smallint NOT NULL DEFAULT 0,
    added timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    addedby smallint NOT NULL DEFAULT 0,
    PRIMARY KEY (id)
);

CREATE TABLE album_ratings (
    albumid smallint NOT NULL DEFAULT 0,
    rating smallint NOT NULL DEFAULT 0
);

CREATE TABLE album_reviews (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    albumid integer,
    title text,
    review text,
    addedby integer,
    added timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    actionby integer,
    status smallint DEFAULT 0,
    PRIMARY KEY (id)
);

CREATE TABLE altnames_lookup (
    artistid integer NOT NULL DEFAULT 0,
    altname text,
    status integer NOT NULL DEFAULT 999
);
CREATE INDEX i_altnames_lookup_artistid ON altnames_lookup (artistid);
CREATE UNIQUE INDEX u_altnames_lookup ON altnames_lookup (artistid, lower(altname));

CREATE TABLE artists (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    name varchar(250),
    disambiguation varchar(190) NOT NULL DEFAULT '',
    urlname varchar(40) NOT NULL DEFAULT '',
    realname text,
    concertinfo text,
    since date,
    since_precision varchar(5) NOT NULL DEFAULT 'day' CHECK (since_precision IN ('day', 'month', 'year')),
    till date,
    till_precision varchar(5) NOT NULL DEFAULT 'day' CHECK (till_precision IN ('day', 'month', 'year')),
    type varchar(1) NOT NULL DEFAULT 'x' CHECK (type IN ('m', 'f', 'b', 'x')),
    special smallint NOT NULL DEFAULT 0,
    trivia text NOT NULL,
    website text NOT NULL,
    addedby integer,
    added timestamp(0) DEFAULT CURRENT_TIMESTAMP,
    updatedby integer,
    updated timestamp(0),
    viewed integer NOT NULL DEFAULT 0,
    status integer NOT NULL DEFAULT 999,
    profile text,
    hits integer NOT NULL DEFAULT 0,
    PRIMARY KEY (id)
);
CREATE UNIQUE INDEX u_artists_name ON artists (lower(name), lower(disambiguation));

CREATE TABLE artists_everyweek (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    aid integer NOT NULL DEFAULT 0,
    added timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    addedby smallint NOT NULL DEFAULT 0
);
CREATE UNIQUE INDEX u_artists_everyweek_id ON artists_everyweek (id);

CREATE TABLE artists_photos (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    artistid integer NOT NULL DEFAULT 0,
    filename text NOT NULL,
    width integer,
    height integer,
    sha256 varchar(64),
    mime varchar(32),
    description text NOT NULL,
    main varchar(1) NOT NULL DEFAULT 'n' CHECK (main IN ('y', 'n')),
    source text NOT NULL,
    sourceurl text NOT NULL,
    licence varchar(64),
    licence_url varchar(500),
    credit varchar(255),
    modified smallint NOT NULL DEFAULT 0,
    addedby smallint NOT NULL DEFAULT 0,
    added timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id)
);
CREATE UNIQUE INDEX u_artists_photos ON artists_photos (artistid, sha256);

CREATE TABLE artist_city_lookup (
    cityid integer NOT NULL DEFAULT 0,
    artistid integer NOT NULL DEFAULT 0,
    status integer NOT NULL DEFAULT 999
);
CREATE UNIQUE INDEX u_artist_city_lookup ON artist_city_lookup (artistid, cityid);

CREATE TABLE artist_concert_lookup (
    artistid integer,
    concertid integer
);

CREATE TABLE artist_lookup (
    songid integer NOT NULL DEFAULT 0,
    artistid integer NOT NULL DEFAULT 0,
    status integer NOT NULL DEFAULT 999
);
CREATE INDEX i_artist_lookup_artistid ON artist_lookup (artistid);
CREATE INDEX i_artist_lookup_songid ON artist_lookup (songid);
CREATE UNIQUE INDEX u_artist_lookup ON artist_lookup (songid, artistid);

CREATE TABLE artist_merges (
    id integer NOT NULL,
    into_id integer NOT NULL,
    review_item_id integer,
    merged timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id)
);
CREATE INDEX i_artist_merges_into ON artist_merges (into_id);

CREATE TABLE band_lookup (
    artistid integer NOT NULL DEFAULT 0,
    bandid integer NOT NULL DEFAULT 0,
    insince date,
    insince_precision varchar(5) NOT NULL DEFAULT 'day' CHECK (insince_precision IN ('day', 'month', 'year')),
    awaysince date,
    awaysince_precision varchar(5) NOT NULL DEFAULT 'day' CHECK (awaysince_precision IN ('day', 'month', 'year')),
    status integer NOT NULL DEFAULT 999
);
CREATE UNIQUE INDEX u_band_lookup ON band_lookup (artistid, bandid);

CREATE TABLE captcha_challenges (
    token varchar(32) NOT NULL,
    answer smallint NOT NULL,
    created timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (token)
);
CREATE INDEX i_captcha_challenges_created ON captcha_challenges (created);

CREATE TABLE cities (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    name text,
    addedby integer,
    added timestamp(0) DEFAULT CURRENT_TIMESTAMP,
    updatedby integer,
    updated timestamp(0),
    viewed integer NOT NULL DEFAULT 0,
    status integer NOT NULL DEFAULT 999,
    description text,
    PRIMARY KEY (id)
);

CREATE TABLE city_label_lookup (
    cityid integer NOT NULL DEFAULT 0,
    labelid integer NOT NULL DEFAULT 0,
    status integer NOT NULL DEFAULT 999
);
CREATE UNIQUE INDEX u_city_label_lookup ON city_label_lookup (labelid, cityid);

CREATE TABLE collection (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    albumid integer,
    userid integer,
    added timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id)
);
CREATE UNIQUE INDEX u_collection ON collection (albumid, userid);

CREATE TABLE edit_journal (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    operation_id integer NOT NULL,
    table_name varchar(64) COLLATE "C" NOT NULL,
    action varchar(8) COLLATE "C" NOT NULL CHECK (action IN ('inserted', 'changed', 'deleted')),
    row_before json,
    row_after json,
    PRIMARY KEY (id)
);
CREATE INDEX i_edit_journal_operation ON edit_journal (operation_id);

CREATE TABLE edit_operations (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    operation varchar(32) COLLATE "C" NOT NULL,
    args json NOT NULL,
    user_id integer NOT NULL,
    why varchar(500) COLLATE "C" NOT NULL,
    path varchar(5) COLLATE "C" NOT NULL CHECK (path IN ('cli', 'panel')),
    created timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    undone_by integer,
    PRIMARY KEY (id)
);

CREATE TABLE external_ids (
    entity_type varchar(6) COLLATE "C" NOT NULL CHECK (entity_type IN ('album', 'artist', 'label', 'song')),
    entity_id integer NOT NULL,
    source varchar(32) COLLATE "C" NOT NULL,
    kind varchar(32) COLLATE "C" NOT NULL,
    value varchar(190) COLLATE "C" NOT NULL,
    added timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (source, kind, value)
);
CREATE INDEX i_external_ids_entity ON external_ids (entity_type, entity_id);

CREATE TABLE feattypes (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    feattype text,
    status integer NOT NULL DEFAULT 999,
    PRIMARY KEY (id)
);
CREATE UNIQUE INDEX u_feattypes ON feattypes (lower(feattype));

CREATE TABLE feature_lookup (
    songid integer NOT NULL DEFAULT 0,
    artistid integer NOT NULL DEFAULT 0,
    feattype integer NOT NULL DEFAULT 0,
    status integer NOT NULL DEFAULT 999
);
CREATE INDEX i_feature_lookup_artistid ON feature_lookup (artistid);
CREATE INDEX i_feature_lookup_songid ON feature_lookup (songid);
CREATE UNIQUE INDEX u_feature_lookup ON feature_lookup (songid, artistid, feattype);

CREATE TABLE hhb_comments (
    com_id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    com_content text,
    com_author text,
    com_author_ip text,
    com_author_id integer NOT NULL,
    com_object_type varchar(1) NOT NULL CHECK (com_object_type IN ('a', 'n', 'p', 'l', 's', 'u')),
    com_object_id integer,
    com_added timestamp(0),
    com_updated timestamp(0),
    com_updated_by integer,
    PRIMARY KEY (com_id)
);
CREATE INDEX com_object_id_index ON hhb_comments (com_object_id);

CREATE TABLE hhb_users (
    usr_id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    usr_email varchar(100) NOT NULL,
    usr_password varchar(255) NOT NULL,
    usr_display_name varchar(30),
    usr_first_name varchar(100),
    usr_last_name varchar(100),
    usr_recovery_key varchar(32) DEFAULT '',
    usr_is_admin varchar(3) NOT NULL DEFAULT 'no' CHECK (usr_is_admin IN ('yes', 'no')),
    usr_added timestamp(0),
    usr_updated timestamp(0),
    usr_last_login timestamp(0),
    usr_login_count integer NOT NULL DEFAULT 0,
    PRIMARY KEY (usr_id)
);

CREATE TABLE hhb_user_lyrics_edit (
    ule_id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    ule_user_id integer,
    ule_lyrics_id integer,
    ule_action_type varchar(6) NOT NULL CHECK (ule_action_type IN ('add', 'edit', 'delete')),
    ule_action_timestamp timestamp(0),
    ule_lyrics text,
    PRIMARY KEY (ule_id)
);
CREATE INDEX i_hhb_user_lyrics_edit_ule_lyrics_id ON hhb_user_lyrics_edit (ule_lyrics_id);

CREATE TABLE import_provenance (
    entity_type varchar(6) COLLATE "C" NOT NULL CHECK (entity_type IN ('album', 'artist', 'label', 'song', 'image')),
    entity_id integer NOT NULL,
    field varchar(64) COLLATE "C" NOT NULL,
    source varchar(32) COLLATE "C" NOT NULL,
    source_ref varchar(500) COLLATE "C" NOT NULL,
    licence varchar(64) COLLATE "C",
    fetched timestamp(0) NOT NULL,
    run_id integer NOT NULL,
    added timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (entity_type, entity_id, field, source)
);
CREATE INDEX i_import_provenance_run ON import_provenance (run_id);

CREATE TABLE import_runs (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    batch varchar(190) COLLATE "C" NOT NULL,
    batch_sha256 varchar(64) COLLATE "C" NOT NULL,
    mode varchar(7) COLLATE "C" NOT NULL CHECK (mode IN ('dry-run', 'apply')),
    started timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    finished timestamp(0),
    created_count integer NOT NULL DEFAULT 0,
    updated_count integer NOT NULL DEFAULT 0,
    unchanged_count integer NOT NULL DEFAULT 0,
    skipped_count integer NOT NULL DEFAULT 0,
    refused_count integer NOT NULL DEFAULT 0,
    report json,
    PRIMARY KEY (id)
);

CREATE TABLE labels (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    name varchar(250),
    urlname varchar(40) NOT NULL DEFAULT '',
    website text,
    email text,
    addres text,
    addedby integer,
    added timestamp(0) DEFAULT CURRENT_TIMESTAMP,
    updatedby integer,
    updated timestamp(0),
    viewed integer NOT NULL DEFAULT 0,
    status integer NOT NULL DEFAULT 999,
    profile text,
    logo text NOT NULL,
    hits integer NOT NULL DEFAULT 0,
    PRIMARY KEY (id)
);
CREATE UNIQUE INDEX u_labels_name ON labels (lower(name));

CREATE TABLE migration_archive (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    version varchar(4) COLLATE "C" NOT NULL,
    table_name varchar(64) COLLATE "C" NOT NULL,
    action varchar(8) COLLATE "C" NOT NULL CHECK (action IN ('deleted', 'inserted', 'changed')),
    row_data json NOT NULL,
    added timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id)
);
CREATE INDEX i_migration_archive_version ON migration_archive (version, table_name, action);

CREATE TABLE music_lookup (
    songid integer NOT NULL DEFAULT 0,
    artistid integer NOT NULL DEFAULT 0,
    status integer NOT NULL DEFAULT 999
);
CREATE INDEX i_music_lookup_artistid ON music_lookup (artistid);
CREATE INDEX i_music_lookup_songid ON music_lookup (songid);
CREATE UNIQUE INDEX u_music_lookup ON music_lookup (songid, artistid);

CREATE TABLE news (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    news text,
    title text,
    expires timestamp(0),
    glyph text NOT NULL,
    graph text NOT NULL,
    viewed integer NOT NULL DEFAULT 0,
    addedby integer,
    added timestamp(0) DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id)
);

CREATE TABLE news_album_lookup (
    newsid integer NOT NULL DEFAULT 0,
    albumid integer NOT NULL DEFAULT 0
);

CREATE TABLE news_artist_lookup (
    newsid integer NOT NULL DEFAULT 0,
    artistid integer NOT NULL DEFAULT 0
);

CREATE TABLE news_city_lookup (
    newsid integer NOT NULL DEFAULT 0,
    cityid integer NOT NULL DEFAULT 0
);

CREATE TABLE news_concert_lookup (
    newsid integer NOT NULL DEFAULT 0,
    concertid integer NOT NULL DEFAULT 0
);

CREATE TABLE news_label_lookup (
    newsid integer NOT NULL DEFAULT 0,
    labelid integer NOT NULL DEFAULT 0
);

CREATE TABLE page_views (
    entity_type varchar(6) COLLATE "C" NOT NULL CHECK (entity_type IN ('album', 'artist', 'song', 'label', 'news')),
    entity_id integer NOT NULL,
    day date NOT NULL,
    views integer NOT NULL DEFAULT 0,
    PRIMARY KEY (entity_type, day, entity_id)
);
CREATE INDEX i_page_views_entity ON page_views (entity_type, entity_id, day);

CREATE TABLE ratings (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    albumid integer,
    userid integer,
    rate integer,
    added timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id)
);
CREATE UNIQUE INDEX u_ratings ON ratings (albumid, userid);

CREATE TABLE ratings_avg (
    albumid smallint NOT NULL DEFAULT 0,
    rating real NOT NULL DEFAULT 0,
    PRIMARY KEY (albumid)
);

CREATE TABLE remix_lookup (
    songid integer NOT NULL DEFAULT 0,
    artistid integer NOT NULL DEFAULT 0,
    name text,
    status integer NOT NULL DEFAULT 999
);
CREATE INDEX i_remix_lookup_artistid ON remix_lookup (artistid);
CREATE UNIQUE INDEX u_remix_lookup ON remix_lookup (songid, artistid);

CREATE TABLE review_items (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    entity_type varchar(6) COLLATE "C" NOT NULL CHECK (entity_type IN ('album', 'artist', 'label', 'song')),
    entity_id integer NOT NULL,
    reason varchar(64) COLLATE "C" NOT NULL,
    detail json,
    run_id integer,
    created timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    resolved timestamp(0),
    resolved_by integer,
    resolution varchar(64) COLLATE "C",
    note text COLLATE "C",
    undo_data json,
    PRIMARY KEY (id)
);
CREATE INDEX i_review_items_entity ON review_items (entity_type, entity_id, resolved);
CREATE INDEX i_review_items_open ON review_items (resolved, reason);

CREATE TABLE scratch_lookup (
    songid integer NOT NULL DEFAULT 0,
    artistid integer NOT NULL DEFAULT 0,
    status integer NOT NULL DEFAULT 999
);
CREATE INDEX i_scratch_lookup_artistid ON scratch_lookup (artistid);
CREATE INDEX i_scratch_lookup_songid ON scratch_lookup (songid);
CREATE UNIQUE INDEX u_scratch_lookup ON scratch_lookup (songid, artistid);

CREATE TABLE searches (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    searchstring text,
    userid integer,
    added timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id)
);

CREATE TABLE songs (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    title text,
    urlname varchar(40) NOT NULL DEFAULT '',
    length integer,
    bpm real,
    acapella smallint,
    radio smallint,
    instrumental smallint,
    addedby integer,
    added timestamp(0) DEFAULT CURRENT_TIMESTAMP,
    updatedby integer,
    updated timestamp(0),
    viewed integer NOT NULL DEFAULT 0,
    status integer NOT NULL DEFAULT 999,
    description text,
    lyrics text NOT NULL,
    youtube_url varchar(255),
    youtube_url_flag integer NOT NULL DEFAULT 0,
    PRIMARY KEY (id)
);
CREATE INDEX i_songs_viewed ON songs (viewed);
COMMENT ON COLUMN songs.youtube_url_flag IS 'number of ''wrong video'' flags';

CREATE TABLE song_samples (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    songid integer,
    sample text,
    addedby integer,
    added timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    status smallint NOT NULL DEFAULT 0,
    PRIMARY KEY (id)
);

CREATE TABLE submision_errors (
    id smallint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    added timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    addedby varchar(50) NOT NULL DEFAULT '0',
    site text NOT NULL,
    sid text NOT NULL,
    message text NOT NULL,
    status varchar(1) NOT NULL DEFAULT 'w' CHECK (status IN ('w', 'r', 'a')),
    PRIMARY KEY (id)
);

CREATE TABLE submision_recommendations (
    id smallint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    email text NOT NULL,
    signature text NOT NULL,
    link text NOT NULL,
    added timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id)
);

CREATE TABLE users (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    login varchar(16),
    pass varchar(32),
    name varchar(50),
    urlname varchar(50) NOT NULL DEFAULT '',
    email varchar(50),
    www varchar(50),
    place varchar(50),
    timesloggedin integer DEFAULT 0,
    lastlogin timestamp(0),
    added timestamp(0),
    about text,
    status integer DEFAULT 0,
    gender integer DEFAULT 0,
    woje integer DEFAULT 0,
    birthyear smallint NOT NULL DEFAULT 0,
    allow_wishlist varchar(1) NOT NULL DEFAULT 'y' CHECK (allow_wishlist IN ('y', 'n')),
    allow_collection varchar(1) NOT NULL DEFAULT 'y' CHECK (allow_collection IN ('y', 'n')),
    viewed integer NOT NULL DEFAULT 0,
    hhb_usr_id integer,
    PRIMARY KEY (id)
);
CREATE UNIQUE INDEX u_users_hhb_usr_id ON users (hhb_usr_id);

CREATE TABLE users_activations (
    userid integer,
    activationstring text
);

CREATE TABLE users_admins (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    login varchar(16),
    pass varchar(32),
    name varchar(50),
    email varchar(50),
    timesloggedin integer DEFAULT 0,
    lastlogin timestamp(0),
    added timestamp(0),
    news_priv varchar(1) NOT NULL DEFAULT 'n' CHECK (news_priv IN ('y', 'n')),
    conc_priv varchar(1) NOT NULL DEFAULT 'n' CHECK (conc_priv IN ('y', 'n')),
    week_priv varchar(1) NOT NULL DEFAULT 'n' CHECK (week_priv IN ('y', 'n')),
    lala_priv varchar(1) NOT NULL DEFAULT 'n' CHECK (lala_priv IN ('y', 'n')),
    PRIMARY KEY (id)
);

CREATE TABLE wishlist (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    albumid integer,
    userid integer,
    added timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id)
);
CREATE UNIQUE INDEX u_wishlist ON wishlist (albumid, userid);

ALTER TABLE edit_journal ADD CONSTRAINT fk_edit_journal_operation FOREIGN KEY (operation_id) REFERENCES edit_operations (id);
ALTER TABLE import_provenance ADD CONSTRAINT fk_import_provenance_run FOREIGN KEY (run_id) REFERENCES import_runs (id);
